#include <iostream>
#include <map>
using namespace std;

int main() {
    int n = 0;
    cin >> n;

    map<int, int> tally;
    for (int i = 0; i < n; i++) {
        int x = 0;
        cin >> x;
        tally[x] += 1;
    }

    for (auto p : tally) {
        cout << p.first << " " << p.second << endl;
    }
    cout << tally.size() << endl;
    return 0;
}
